import { cn } from '@/lib/utils'

export type BookingStatus =
  | 'pending'
  | 'confirmed'
  | 'in-progress'
  | 'completed'
  | 'cancelled'
  | 'no-show'

const STATUS_LABELS: Record<BookingStatus, string> = {
  pending: 'Pending',
  confirmed: 'Confirmed',
  'in-progress': 'In Progress',
  completed: 'Completed',
  cancelled: 'Cancelled',
  'no-show': 'No-show',
}

const STATUS_CLASSES: Record<BookingStatus, string> = {
  pending: 'badge-pending',
  confirmed: 'badge-confirmed',
  'in-progress': 'badge-in-progress',
  completed: 'badge-completed',
  cancelled: 'badge-cancelled',
  'no-show': 'badge-no-show',
}

interface StatusBadgeProps {
  status: BookingStatus
  className?: string
}

export function StatusBadge({ status, className }: StatusBadgeProps) {
  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium',
        STATUS_CLASSES[status],
        className,
      )}
    >
      {STATUS_LABELS[status]}
    </span>
  )
}
'use client'

import type { LucideIcon } from 'lucide-react'
import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { cn } from '@/lib/utils'

interface KpiCardProps {
  label: string
  value: string | number
  subtext: string
  icon: LucideIcon
  trend?: 'up' | 'down' | 'neutral'
  /** When true, lower value is better (e.g., no-show rate). Inverts trend color logic. */
  invertTrend?: boolean
  loading?: boolean
  index?: number
}

function getTrendColor(trend: 'up' | 'down' | 'neutral', invertTrend: boolean): string {
  if (trend === 'neutral') return 'text-muted-foreground'
  const isPositive = invertTrend ? trend === 'down' : trend === 'up'
  return isPositive ? 'text-emerald-500' : 'text-destructive'
}

export function KpiCard({
  label,
  value,
  subtext,
  icon: Icon,
  trend = 'neutral',
  invertTrend = false,
  index = 0,
}: KpiCardProps) {
  return (
    <Card
      className="kpi-card-hover border-border/50 shadow-[var(--shadow-card)] animate-fade-in-up"
      style={{
        animationDelay: `${index * 80}ms`,
