/**
 * Server-side feature gating.
 *
 * Returns whether a studio on a given plan tier has access to a feature.
 * For API routes: call requireFeature() to return a 403 response automatically.
 */

export type PlanTier = 'solo' | 'studio' | 'pro' | 'enterprise'

const PLAN_ORDER: Record<PlanTier, number> = {
  solo: 0,
  studio: 1,
  pro: 2,
  enterprise: 3,
}

/** Minimum plan required for each feature key */
const FEATURE_MIN_PLAN: Record<string, PlanTier> = {
  inventory: 'studio',
  commissions: 'studio',
  payroll: 'pro',
  ai_design: 'pro',
  guest_artists: 'pro',
  eu_reach: 'pro',
  multi_location: 'pro',
  white_label: 'enterprise',
  api_access: 'enterprise',
}

/**
 * Returns true if the given plan includes the feature.
 */
export function hasFeature(plan: PlanTier, feature: string): boolean {
  const minPlan = FEATURE_MIN_PLAN[feature]
  if (!minPlan) return true // unknown feature = available everywhere
  return PLAN_ORDER[plan] >= PLAN_ORDER[minPlan]
}

/**
 * Returns the minimum plan required for a feature, or null if always available.
 */
export function requiredPlanFor(feature: string): PlanTier | null {
  return FEATURE_MIN_PLAN[feature] ?? null
}

/**
 * Throws a structured error if the plan doesn't include the feature.
 * Use in API Route Handlers:
 *   const guard = requireFeature(studioplan, 'ai_design')
 *   if (guard) return guard
 */
export function requireFeature(
  plan: PlanTier,
  feature: string,
): Response | null {
  if (hasFeature(plan, feature)) return null
  const required = FEATURE_MIN_PLAN[feature] ?? 'pro'
  return Response.json(
    { error: 'Feature not available on current plan', requiredPlan: required },
    { status: 403 },
  )
}

import { cookies } from 'next/headers'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { SidebarProvider } from '@/components/ui/sidebar'
import { AppSidebar } from '@/components/app/sidebar/AppSidebar'
import { AppHeader } from '@/components/app/sidebar/AppHeader'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface AppLayoutProps {
  children: React.ReactNode
}

export default async function AppLayout({ children }: AppLayoutProps) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    redirect('/login')
  }

  // Fetch profile, studio membership, and studio in parallel
  const [profileResult, memberResult] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name, avatar_url')
      .eq('id', user.id)
      .single(),
    supabase
      .from('studio_members')
      .select('role, studio_id, studios(id, name, slug, logo_url, plan_id)')
      .eq('user_id', user.id)
      .order('created_at', { ascending: true })
      .limit(1)
      .single(),
  ])

  // Graceful fallbacks — layout must never crash
  const profile = profileResult.data
  const member = memberResult.data

  const studioName = (member?.studios as { name: string } | null)?.name ?? 'My Studio'
  const studioLogoUrl =
    (member?.studios as { logo_url: string | null } | null)?.logo_url ?? null
  const studioId = member?.studio_id ?? null
  const role: NavRole =
    (member?.role as NavRole | undefined) ?? 'owner'

  // Subscription / plan
  let plan: PlanTier = 'solo'
  if (studioId) {
    const subResult = await supabase
      .from('subscriptions')
      .select('plan_tier')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .maybeSingle()
    if (subResult.data?.plan_tier) {
      plan = subResult.data.plan_tier as PlanTier
    }
  }

  // Location count (for multi-location nav group)
  let locationCount = 0
  if (studioId) {
    const locResult = await supabase
      .from('locations')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
    locationCount = locResult.count ?? 0
  }

  // Sidebar default-open state from cookie
  const cookieStore = await cookies()
  const sidebarOpen = cookieStore.get('sidebar_state')?.value !== 'false'

  const userName = profile?.full_name ?? user.email?.split('@')[0] ?? 'You'
  const userEmail = user.email ?? ''
  const userAvatarUrl = profile?.avatar_url ?? null

  return (
    <SidebarProvider defaultOpen={sidebarOpen} className="h-svh">
      <AppSidebar
        locationCount={locationCount}
        plan={plan}
        user={{ name: userName, email: userEmail, avatarUrl: userAvatarUrl }}
        studioName={studioName}
        studioLogoUrl={studioLogoUrl}
        role={role}
      />
      <AppHeader
        studioName={studioName}
        userName={userName}
        userEmail={userEmail}
        userAvatarUrl={userAvatarUrl}
      >
        {children}
      </AppHeader>
    </SidebarProvider>
  )
}
