const handleDepositCheckout = async () => {
  setCheckoutLoading(true)
  try {
    const res = await fetch(`/api/public/bookings/${bookingToken}/checkout`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'deposit' }),
