            onChange={e => setRefundAmount(e.target.value)}
            className="pl-7 tabular-nums"
          />
        </div>
        <p className="text-xs text-muted-foreground">
          Max {formatCurrency(booking.deposit_cents)}
        </p>
      </div>

      {/* Reason field */}
      <div className="space-y-1.5">
        <Label className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
          Reason <span className="normal-case font-normal">(optional)</span>
        </Label>
        <Textarea
          value={reason}
          onChange={e => setReason(e.target.value)}
          placeholder="Client request, duplicate booking, etc."
          className="h-20 resize-none text-sm"
          maxLength={500}
        />
      </div>

      {/* Error state */}
      {refundError && (
        <div className="rounded-lg bg-destructive/10 border border-destructive/30 p-3 text-xs text-destructive">
          {refundError}
        </div>
      )}
    </div>

    <DialogFooter>
      <Button variant="outline" onClick={() => setOpen(false)} disabled={loading}>
        Cancel
      </Button>
      <Button
        variant="destructive"
        onClick={handleRefund}
        disabled={loading || !refundAmount}
      >
        {loading ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" /> : null}
        Refund {refundAmount ? formatCurrency(Math.round(parseFloat(refundAmount) * 100)) : ''}
      </Button>
    </DialogFooter>
  </DialogContent>
</Dialog>
```

